    72→\subsection{The Chemical Master Equation}
    73→
    74→\begin{definition}[Chemical Master Equation (CME)]
    75→The \textit{Chemical Master Equation (CME)} describes the time evolution of the probability distribution $p(\boldsymbol{x}, t)$ over the state $\boldsymbol{x}$. For a single state $\boldsymbol{x}$, the CME is
    76→\begin{equation}
    77→    \frac{d}{dt} p(\boldsymbol{x}, t) =
    78→    \sum_{k=1}^{M} \big[\alpha_k(\boldsymbol{x} - \boldsymbol{\nu}_k)\, p(\boldsymbol{x} - \boldsymbol{\nu}_k, t)
    79→    - \alpha_k(\boldsymbol{x})\, p(\boldsymbol{x}, t)\big],
    80→\end{equation}
    81→where $\alpha_k(\boldsymbol{x})$ is the propensity for reaction $k$ at state $\boldsymbol{x}$ and $\boldsymbol{\nu}_k$ is its stoichiometric change vector.
    82→
    83→For the entire state space $\mathbf{X}$, the CME can be written in matrix form as
    84→\begin{equation}
    85→    \frac{d}{dt}\, \boldsymbol{p}(\mathbf{X}, t) = \mathbf{A}\, \boldsymbol{p}(\mathbf{X}, t),
    86→\end{equation}
    87→where $\boldsymbol{p}(\mathbf{X}, t)$ is the probability vector over $\mathbf{X}$ and the \textit{generator matrix} $\mathbf{A}$ has entries
    88→\begin{align}
    89→    \mathbf{A}_{ij} =
    90→    \begin{cases}
    91→        -\displaystyle\sum_{k=1}^{M} \alpha_k(\mathbf{X}_j), & \text{if } i=j, \\
    92→         \alpha_k(\mathbf{X}_j) & \text{if }\, \mathbf{X}_i=\mathbf{X}_j+\boldsymbol{\nu}_k, \\
    93→    \end{cases}
    94→\end{align}
    95→and $\mathbf{A}_{ij}=0$ when no reaction connects $\mathbf{X}_j$ to $\mathbf{X}_i$.
    96→\end{definition}
