   547→\begin{corollary}[Truncated generator contraction]
   548→\label{cor:truncated-contraction}
   549→The truncated generator $\mathbf{A}_{JJ}$ with non-positive column sums generates a positive contraction semigroup satisfying $e^{t\mathbf{A}_{JJ}} \geq 0$ and $\|e^{t\mathbf{A}_{JJ}}\|_{1 \to 1} \le 1$ for all $t \ge 0$.
   550→\end{corollary}
   551→
   552→\begin{proof}
   553→For the norm bound, consider any $\boldsymbol{p}(0) \geq \mathbf{0}$ with $\|\boldsymbol{p}(0)\|_1 = 1$. Since $\mathbf{1}^\top \mathbf{A}_{JJ} \leq \mathbf{0}^\top$, we have
   554→\begin{equation}
   555→\frac{d}{dt}\|\boldsymbol{p}(t)\|_1 = \mathbf{1}^\top \mathbf{A}_{JJ}\boldsymbol{p}(t) = (\mathbf{1}^\top \mathbf{A}_{JJ})\boldsymbol{p}(t) \leq 0,
   556→\end{equation}
   557→which gives $\|e^{t\mathbf{A}_{JJ}}\|_{1 \to 1} \leq 1$. Positivity follows by the same shifting argument as in Proposition~\ref{prop:compressed-generator}.
   558→\end{proof}
   559→
   560→\begin{remark}[Infinite-dimensional extension]
   561→\label{rem:infinite-dimensional}
   562→The arguments in Proposition~\ref{prop:compressed-generator} and Corollary~\ref{cor:truncated-contraction} extend to the full CME on infinite state space $\mathcal{X}$ via the Hille-Yosida theorem~\cite{Ethier1986,pazy_1983}. In the infinite-dimensional setting, the operator $\mathbf{A}$ is unbounded on $\ell^1(\mathcal{X})$, requiring verification that $\mathbf{A}$ is closed with dense domain $D(\mathbf{A})$ and that the resolvent bounds $\|(\lambda I - \mathbf{A})^{-1}\|_{1 \to 1} \leq 1/\lambda$ hold for all $\lambda > 0$. These conditions guarantee that $\mathbf{A}$ generates a strongly continuous contraction semigroup. In our finite-dimensional truncation to $J$, all operators are automatically bounded and closed with domain equal to the entire space.
   563→\end{remark}
   564→
   565→
   566→
   567→\subsection{Local Error}
   568→
   569→We decompose the local error into model error from state space truncation and time-stepping error from numerical approximation.
   570→
   571→\subsubsection{Model Error from State Space Truncation}
   572→
   573→Consider the dynamics on $J$ starting from the true state $\boldsymbol{p}_J(t_n)$. The true restricted dynamics satisfy
   574→
   575→\begin{equation}
   576→\label{eq:true-restricted}
   577→\frac{d}{dt} \boldsymbol{p}_J(t) = \mathbf{A}_{JJ}\boldsymbol{p}_J(t) + \mathbf{A}_{JJ'}\boldsymbol{p}_{J'}(t),
   578→\end{equation}
   579→while the compressed dynamics evolve according to
   580→\begin{equation}
   581→\label{eq:compressed-dynamics-exact}
   582→\frac{d}{dt} \widehat{\boldsymbol{p}}_J(t) = \widetilde{\mathbf{A}}_{JJ}\widehat{\boldsymbol{p}}_J(t).
   583→\end{equation}
   584→Define the local model error $\boldsymbol{\varepsilon}(t) := \boldsymbol{p}_J(t) - \widehat{\boldsymbol{p}}_J(t)$ with $\boldsymbol{\varepsilon}(t_n) = \mathbf{0}$.
   585→
   586→\begin{theorem}[Local model error bound]
   587→\label{thm:local-model-error}
   588→Over a single time step $[t_n, t_{n+1}]$, the local model error satisfies
   589→\begin{equation}
   590→\|\boldsymbol{\varepsilon}(t_{n+1})\|_1 \leq \int_{t_n}^{t_{n+1}} (\Phi_{\mathrm{in}}(s) + \Phi_{\mathrm{out}}(s)) \; ds.
   591→\end{equation}
   592→where $\Phi_{\mathrm{in}}$ and $\Phi_{\mathrm{out}}$ are boundary fluxes entering and leaving the truncation boundary respectively (Eq.~\eqref{eq:flux-defs}).
   593→\end{theorem}
   594→
   595→\begin{proof}
   596→Subtracting Eq.~\eqref{eq:compressed-dynamics-exact} from Eq.~\eqref{eq:true-restricted} gives the following inhomogeneous equation,
   597→\begin{align*}
   598→\frac{d}{dt}\boldsymbol{\varepsilon}(t) &= \mathbf{A}_{JJ}\boldsymbol{\varepsilon}(t) + \underbrace{\mathbf{A}_{JJ'}\boldsymbol{p}_{J'}(t) - \diag(\mathbf{1}^\top\mathbf{A}_{J'J})\widehat{\boldsymbol{p}}_J(t)}_{=: \boldsymbol{f}(t)}.
   599→\end{align*}
   600→The solution of the inhomogeneous ODE is given by,
   601→\begin{align}
   602→\boldsymbol{\varepsilon}(t_{n+1}) &= \int_{t_n}^{t_{n+1}} e^{(t_{n+1}-s)\mathbf{A}_{JJ}}\boldsymbol{f}(s) \, ds + e^{A_{JJ}}\varepsilon(t_n). \\
   603→\end{align}
   604→We set the initial condition $\varepsilon(t_n)$ to zero as we start both systems with same initial condition. Eliminating the initial condition and taking the $\ell_1$ norm both sides, we get:
   605→\begin{align}
   606→\|\boldsymbol{\varepsilon}(t_{n+1})\|_1 &\leq \int_{t_n}^{t_{n+1}} \underbrace{\|e^{(t_{n+1}-s)\mathbf{A}_{JJ}}\|_{1}}_{\leq 1 (\text{Corollary \ref{cor:truncated-contraction}})}\|\boldsymbol{f}(s)\|_1 \, ds \\
   607→&\leq \int_{t_n}^{t_{n+1}} \left(\|\mathbf{A}_{JJ'}\boldsymbol{p}_{J'}(s)\|_1  +\|\diag(\mathbf{1}^\top\mathbf{A}_{J'J})\widehat{\boldsymbol{p}}_J(s)\|_1 \right)  \; ds \\
   608→&= \int_{t_n}^{t_{n+1}} ( (\mathbf{1}^\top \mathbf{A}_{JJ'})\boldsymbol{p}_{J'}(s) + (\mathbf{1}^\top\mathbf{A}_{J'J})\widehat{\boldsymbol{p}}_J(s)) \;ds \\
   609→&= \int_{t_n}^{t_{n+1}} (\Phi_{\mathrm{in}}(s) + \Phi_{\mathrm{out}}(s)) \; ds.
   610→\end{align}
   611→
   612→\end{proof}
   613→
   614→While potentially conservative, this characterization provides a computationally tractable error estimate based on readily available flux quantities. We next analyze the accumulation of these local errors over multiple time steps.
   615→
   616→\subsubsection{Matrix Exponential Approximation Error}
   617→\label{subsec:time_stepping_error_analysis}
   618→
   619→In addition to state-space truncation, we approximate the matrix exponential $\exp(\widetilde{\mathbf{A}}_{JJ}\,\Delta t)$ numerically. 
   620→
   621→\begin{proposition}[Local time-stepping error]
   622→\label{prop:local_time_error}
   623→For a matrix exponential approximation with tolerance $\epsilon_{\mathrm{ODE}}$, the error in a single time step is bounded by
   624→\begin{equation}
   625→\|\exp(\widetilde{\mathbf{A}}_{JJ}\,\Delta t)\,\boldsymbol{v} - \mathrm{Approx}(\widetilde{\mathbf{A}}_{JJ}, \Delta t)\,\boldsymbol{v}\|_1 \le \epsilon_{\mathrm{ODE}}\,\|\boldsymbol{v}\|_1.
   626→\end{equation}
   627→Modern Krylov subspace implementations such as EXPOKIT \cite{Sidje1998} provide adaptive mechanisms to control this error by adjusting the Krylov subspace dimension based on the specified tolerance.
   628→\end{proposition}
   629→
   630→\subsection{Global Error}
   631→
   632→\begin{corollary}[Global error bound]
   633→\label{cor:global-error}
   634→Let $e_n := \|\boldsymbol{p}(t_n) - \widetilde{\boldsymbol{p}}_n\|_1$ denote the global error, where $\widetilde{\boldsymbol{p}}_n$ is the numerical solution on $J$ extended with zeros. For $N$ time steps with $e_0 = 0$,
   635→\begin{equation}
   636→e_N \leq \sum_{n=0}^{N-1} (\varepsilon_n + \tau_n),
   637→\end{equation}
   638→where $\varepsilon_n := \int_{t_n}^{t_{n+1}} (\Phi_{\mathrm{in}}(s) + \Phi_{\mathrm{out}}(s)) \, ds$ is the local model error and $\tau_n := \|\widehat{\boldsymbol{p}}_{n+1} - \widetilde{\boldsymbol{p}}_{n+1}\|_1$ is the time-stepping error.
   639→\end{corollary}
   640→
   641→\begin{proof}
   642→We track three sources of discrepancy:
   643→\begin{itemize}
   644→\item $\boldsymbol{p}(t_n)$: true solution on full state space
   645→\item $\widehat{\boldsymbol{p}}_n$: exact solution of compressed dynamics on $J_n$ 
   646→\item $\widetilde{\boldsymbol{p}}_n$: numerical approximation on $J_n$
   647→\end{itemize}
   648→
   649→By the triangle inequality:
   650→\begin{equation}
   651→e_n = \|\boldsymbol{p}(t_n) - \widetilde{\boldsymbol{p}}_n\|_1 \leq \|\boldsymbol{p}(t_n) - \widehat{\boldsymbol{p}}_n\|_1 + \|\widehat{\boldsymbol{p}}_n - \widetilde{\boldsymbol{p}}_n\|_1.
   652→\end{equation}
